DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261107010635_InitialCreate') THEN
    CREATE TABLE "Producto" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Codigo" character varying(40) NOT NULL,
        "Nombre" character varying(200) NOT NULL,
        "Descripcion" character varying(1000),
        "UnidadMedida" character varying(30) NOT NULL,
        "Peso" numeric(18,3) NOT NULL,
        "PrecioUsd" numeric(18,2) NOT NULL,
        "PartidaArancelaria" character varying(20) NOT NULL,
        "CategoriaId" integer NOT NULL,
        "StockMinimo" numeric(18,3) NOT NULL,
        CONSTRAINT "PK_Producto" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Producto_Peso" CHECK ("Peso" > 0),
        CONSTRAINT "CK_Producto_Precio" CHECK ("PrecioUsd" >= 0),
        CONSTRAINT "CK_Producto_StockMinimo" CHECK ("StockMinimo" >= 0),
        CONSTRAINT "FK_Producto_Categoria_CategoriaId" FOREIGN KEY ("CategoriaId") REFERENCES "Categoria" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261107010635_InitialCreate') THEN
    CREATE TABLE "OrdenVenta" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "EmpleadoId" integer NOT NULL,
        "ClienteId" integer NOT NULL,
        "AlmacenId" integer NOT NULL,
        "Fecha" timestamp with time zone NOT NULL,
        "Estado" integer NOT NULL,
        "Moneda" character varying(3) NOT NULL,
        "TipoCambio" numeric(18,6) NOT NULL,
        "Subtotal" numeric(18,2) NOT NULL,
        "Total" numeric(18,2) NOT NULL,
        "Incoterm" character varying(3) NOT NULL,
        "PaisDestino" character varying(200) NOT NULL,
        CONSTRAINT "PK_OrdenVenta" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_OrdenVenta_Estado" CHECK ("Estado" BETWEEN 0 AND 4),
        CONSTRAINT "CK_OrdenVenta_Importes" CHECK ("TipoCambio" > 0 AND "Subtotal" >= 0 AND "Total" = "Subtotal"),
        CONSTRAINT "FK_OrdenVenta_Almacen_AlmacenId" FOREIGN KEY ("AlmacenId") REFERENCES "Almacen" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_OrdenVenta_Cliente_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Cliente" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_OrdenVenta_Empleado_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleado" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
