        CONSTRAINT "PK_Inventario" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Inventario_Cantidad" CHECK ("Cantidad" >= 0),
        CONSTRAINT "FK_Inventario_Almacen_AlmacenId" FOREIGN KEY ("AlmacenId") REFERENCES "Almacen" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Inventario_Producto_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Producto" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

