        "PrecioUnitario" numeric(18,2) NOT NULL,
        "Subtotal" numeric(18,2) NOT NULL,
        CONSTRAINT "PK_DetalleOrdenVenta" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Detalle_Importes" CHECK ("Cantidad" > 0 AND "PrecioUnitario" >= 0 AND "Subtotal" >= 0),
        CONSTRAINT "FK_DetalleOrdenVenta_OrdenVenta_OrdenVentaId" FOREIGN KEY ("OrdenVentaId") REFERENCES "OrdenVenta" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_DetalleOrdenVenta_Producto_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Producto" ("Id") ON DELETE RESTRICT
