    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261107010635_InitialCreate') THEN
    CREATE TABLE "MovimientoInventario" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ProductoId" integer NOT NULL,
        "AlmacenId" integer NOT NULL,
        "Tipo" integer NOT NULL,
        "Cantidad" numeric(18,3) NOT NULL,
        "Fecha" timestamp with time zone NOT NULL,
        "EmpleadoId" integer NOT NULL,
        "ProveedorId" integer,
        "OrdenVentaId" integer,
        CONSTRAINT "PK_MovimientoInventario" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Movimiento_Cantidad" CHECK (("Tipo" IN (0, 1) AND "Cantidad" > 0) OR ("Tipo" = 2 AND "Cantidad" <> 0)),
        CONSTRAINT "FK_MovimientoInventario_Almacen_AlmacenId" FOREIGN KEY ("AlmacenId") REFERENCES "Almacen" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_MovimientoInventario_Empleado_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleado" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_MovimientoInventario_OrdenVenta_OrdenVentaId" FOREIGN KEY ("OrdenVentaId") REFERENCES "OrdenVenta" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_MovimientoInventario_Producto_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Producto" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_MovimientoInventario_Proveedor_ProveedorId" FOREIGN KEY ("ProveedorId") REFERENCES "Proveedor" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

